const t="conectaSocialCadastro";export function saveRegistration(e){localStorage.setItem(t,JSON.stringify(e))}export function getRegistration(){const e=localStorage.getItem(t);if(!e)return null;try{return JSON.parse(e)}catch(t){return console.error("Não foi possível recuperar o cadastro salvo:",t),clearRegistration(),null}}export function clearRegistration(){localStorage.removeItem(t)}